func (q *Queries) ListShipments(ctx context.Context, arg ListShipmentsParams) ([]Shipment, error) {
	rows, err := q.db.Query(ctx, listShipments,
		arg.StoreID,
		arg.BeforeAt,
		arg.BeforeID,
		arg.OrderID,
		arg.Status,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Shipment{}
	for rows.Next() {
		var i Shipment
		if err := rows.Scan(
			&i.ID,
			&i.StoreID,
			&i.OrderID,
			&i.ConnectionID,
			&i.Carrier,
			&i.Status,
			&i.TrackingNumber,
			&i.ProviderID,
			&i.Currency,
			&i.CodMinor,
			&i.LabelKey,
			&i.RawState,
			&i.Failure,
			&i.CancelRequestedAt,
			&i.StatusAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

