const listZones = `-- name: ListZones :many
SELECT id, store_id, name, rate_minor, free_over_minor, cod_fixed_minor, cod_bp, cod_min_minor, cod_max_minor, position, version, created_at, updated_at, eta_min_days, eta_max_days FROM shipping_zones WHERE store_id = $1 ORDER BY position, id LIMIT 100
`

// A zone holds at least one governorate and a governorate one zone, so a
// store has at most as many zones as its country has governorates (27).
func (q *Queries) ListZones(ctx context.Context, storeID ulid.ID) ([]ShippingZone, error) {
	rows, err := q.db.Query(ctx, listZones, storeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ShippingZone{}
	for rows.Next() {
		var i ShippingZone
		if err := rows.Scan(
			&i.ID,
			&i.StoreID,
			&i.Name,
			&i.RateMinor,
			&i.FreeOverMinor,
			&i.CodFixedMinor,
			&i.CodBp,
			&i.CodMinMinor,
			&i.CodMaxMinor,
			&i.Position,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.EtaMinDays,
			&i.EtaMaxDays,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockZones = `-- name: LockZones :exec
SELECT pg_advisory_xact_lock(hashtextextended('shipping:' || ($1::uuid)::text, 0))
`

// Serializes a store's zone writes (the zone count limit, positions,
// which zone holds a governorate).
func (q *Queries) LockZones(ctx context.Context, storeID ulid.ID) error {
	_, err := q.db.Exec(ctx, lockZones, storeID)
	return err
}

